	@Test
	void scalarFallbackHasNoKnownPhysicalAxisAndCannotEqualADeclaredCpuQuantity() {
		PackedCostVectorArena vectors = new PackedCostVectorArena();
		PackedCostCompletionArena complete = new PackedCostCompletionArena(budget(), vectors,
				new PackedCostAlgebra(vectors));
		int unknown = complete.withObjective(0, 5774.5d);
		assertTrue(unknown > 0);
		assertEquals(0L, vectors.knownMask(unknown));
		int program = complete.completeProgram(unknown, 0, 1.0d, 5774.5d);
		assertEquals(5774.5d, complete.objective(program));
		vectors.resetBuilderToUnknown();
		vectors.setBuilderExact(PackedCostDimensionRegistry.STEADY_STATE_CPU_WORK, 5774.5d);
		int cpu = vectors.internBuilder();
		assertFalse(PackedCostOrder.equal(vectors, unknown, 5774.5d, cpu, 5774.5d));
		assertFalse(PackedCostOrder.dominates(vectors, unknown, 9.0d, cpu, 11.0d));
		assertFalse(PackedCostOrder.dominates(vectors, cpu, 9.0d, unknown, 11.0d));
	}

	@Test
	void legacyScalarCarrierRemainsObservableButCannotReenterQuantityCompletion() {
		PackedQuery query = query();
		try (PackedMemo memo = memo(query)) {
			int group = memo.logicalGroupId(query.rootRelId());
			int physical = memo.addPhysicalAlternative(group, PackedRelOp.STATEMENT_PATTERN,
					query.relPayload(query.rootRelId()), memo.anyPropertyId(), 7, new int[0], 0, 0);
			int winner = memo.offerWinner(group, memo.anyPropertyId(), 0, 0, 0, physical,
					3.0d, 10.0d, 10.0d, new int[0], 0, 0);
			assertEquals(10.0d, memo.costVectors()
					.point(memo.winnerCostVectorId(winner),
							PackedCostDimensionRegistry.STEADY_STATE_CPU_WORK));
			assertEquals(0L, memo.costVectors().knownMask(memo.winnerQuantityVectorId(winner)));
			int child = memo.winnerCostCompletionId(winner);
			assertTrue(child > 0);
			int refused = memo.completeUnaryCostCompletion(0, child, 13.0d);
			PackedCostEstimate local = physical(2.0d, 0.0d);
			PackedCostContext frame = context(1.0d);
			memo.captureUnaryPhysicalCost(local, frame, child);
			int metadata = memo.addPhysicalMetadata(local, 1.0d, 13.0d);
			int result = memo.completeUnaryCostCompletion(metadata, local, child, frame, 13.0d);
			assertTrue(memo.equalCompletedCost(refused, result),
					"an unknown child WORK axis cannot be recovered from its legacy display carrier");
		}
	}

