	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void memoActualContinuationAdmissionKeepsOpposingObjectiveAndResourceTradeoffs(boolean fewerResourcesFirst) {
		PackedQuery query = query();
		try (PackedMemo memo = memo(query)) {
			offer(memo, query, fewerResourcesFirst ? 1.0d : 5.0d, fewerResourcesFirst ? 11.0d : 9.0d, 42, 7);
			int last = offer(memo, query, fewerResourcesFirst ? 5.0d : 1.0d,
					fewerResourcesFirst ? 9.0d : 11.0d, 42, 8);
			assertEquals(2, memo.winnerContinuationFrontierSize(last));
			Set<Double> prices = new HashSet<>();
			for (int winner = memo.firstExactContinuationWinner(memo.logicalGroupId(query.rootRelId()),
					memo.anyPropertyId(), 0, 0, 0); winner != 0; winner = memo.nextExactContinuationWinner(winner)) {
				prices.add(memo.winnerTotalCost(winner));
			}
			assertEquals(Set.of(9.0d, 11.0d), prices);
		}
	}

