	@Test
	void memoComparisonHasStrictObjectiveProductOrderInBothDirections() {
		PackedQuery query = query();
		try (PackedMemo memo = memo(query)) {
			int cheap = child(memo, 1.0d, 9.0d);
			int costly = child(memo, 1.0d, 11.0d);
			int equal = child(memo, 1.0d, 9.0d);
			int otherPopulation = child(memo, 2.5d, 9.0d);
			assertTrue(memo.dominatesCompletedCost(cheap, costly));
			assertFalse(memo.dominatesCompletedCost(costly, cheap));
			assertFalse(memo.dominatesCompletedCost(cheap, equal));
			assertTrue(memo.equalCompletedCost(cheap, equal));
			assertFalse(memo.equalCompletedCost(cheap, costly));
			assertFalse(memo.dominatesCompletedCost(cheap, otherPopulation));
		}
	}

	@Test
	void frontierAdmissionKeepsUnknownMasksAndDifferentInvocationDomainsSeparate() {
		PackedSearchBudget budget = budget();
		PackedCostVectorArena vectors = new PackedCostVectorArena(budget);
		PackedCandidateArena candidates = new PackedCandidateArena(budget);
		PackedParetoFrontierArena frontier = new PackedParetoFrontierArena(budget, candidates, vectors);
		vectors.resetBuilderToUnknown();
		int unknown = vectors.internBuilder();
		vectors.setBuilderExact(PackedCostDimensionRegistry.STEADY_STATE_CPU_WORK, 9.0d);
		int declared = vectors.internBuilder();
		int first = candidates.appendWithQuantities(1, 1, 0, declared, unknown, 1.0d, 0, 0, 1, 11.0d);
		int second = candidates.appendWithQuantities(1, 1, 0, declared, declared, 1.0d, 0, 0, 2, 9.0d);
		int foreign = candidates.appendWithQuantities(1, 1, 0, declared, declared, 2.5d, 0, 0, 3, 7.0d);
		assertEquals(PackedParetoFrontierArena.OfferResult.INSERTED, frontier.offer(1, 1, first));
		assertEquals(PackedParetoFrontierArena.OfferResult.INSERTED, frontier.offer(1, 1, second));
		assertEquals(PackedParetoFrontierArena.OfferResult.INSERTED, frontier.offer(1, 1, foreign));
		assertEquals(3, frontier.size(1, 1));
	}

